import React from "react";
import Swal from "sweetalert2";
import "./Torneo.css";

export default function Torneo() {

  const onSubmit = async (event) => {
    event.preventDefault();
    const formData = new FormData(event.target);

    // puoi cambiare o rimuovere questa parte se usi altro backend
    formData.append("access_key", "YOUR_ACCESS_KEY");

    const object = Object.fromEntries(formData);
    const json = JSON.stringify(object);

    const res = await fetch("https://api.web3forms.com/submit", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json"
      },
      body: json
    }).then((res) => res.json());

    if (res.success) {
      Swal.fire({
        title: "Iscrizione inviata!",
        text: "La tua squadra è stata registrata.",
        icon: "success"
      });

      event.target.reset();
    }
  };

  return (
    <div className="torneo-container">

      <div className="torneo-content">

        <h1 className="torneo-title">Torneo Seriana Cobras 🏀</h1>

        {/* SEZIONE DESCRIZIONE */}
        <div className="torneo-description">

          <p>
            Qui puoi inserire la descrizione del torneo.
            Spiega formato, date, campi, premi e regolamento.
          </p>

          <p>
            Puoi modificare liberamente questo testo direttamente
            nel file <strong>Torneo.jsx</strong>.
          </p>

        </div>


        {/* FORM ISCRIZIONE */}
        <div className="torneo-form-wrapper">

          <h2>Iscrivi la tua squadra</h2>

          <form onSubmit={onSubmit} className="torneo-form">

            <input
              type="text"
              name="nome_squadra"
              placeholder="Nome squadra"
              required
            />

            <input
              type="text"
              name="referente"
              placeholder="Nome referente"
              required
            />

            <input
              type="email"
              name="email"
              placeholder="Email"
              required
            />

            <input
              type="text"
              name="telefono"
              placeholder="Telefono"
            />

            <select name="categoria" required>
              <option value="">Categoria</option>
              <option value="U13">U13</option>
              <option value="U15">U15</option>
              <option value="U17">U17</option>
              <option value="Senior">Senior</option>
            </select>

            <textarea
              name="note"
              placeholder="Note o richieste particolari"
              rows="4"
            />

            <label className="checkbox">
              <input type="checkbox" required />
              Accetto il regolamento del torneo
            </label>

            <button type="submit">Invia iscrizione</button>

          </form>

        </div>

      </div>

    </div>
  );
}
